spec.expr:
sum by (provider, endpoint) (
  rate(
    gurabot_adapter_api_requests_total{
      provider=~"$osu_provider"
    }[$__rate_interval]
  )
) * 60

histogram_quantile(
  0.90,
  sum by (le, provider, endpoint) (
    rate(
      gurabot_adapter_api_request_duration_seconds_bucket{
        provider=~"$osu_provider"
      }[$__rate_interval]
    )
  )
)

100 *
sum(
  rate(
    gurabot_adapter_api_requests_total{
      provider=~"$osu_provider",
      outcome=~"server_error|timeout|network_error|unknown_error"
    }[$__rate_interval]
  )
)
/
clamp_min(
  sum(
    rate(
      gurabot_adapter_api_requests_total{
        provider=~"$osu_provider"
      }[$__rate_interval]
    )
  ),
  0.000001
)

topk(
  10,
  sum by (provider, endpoint) (
    increase(
      gurabot_adapter_api_requests_total{
        provider=~"$osu_provider"
      }[$__range]
    )
  )
)

sum by (service, endpoint) (
  rate(
    gurabot_external_requests_total{
      service=~"$service"
    }[$__rate_interval]
  )
) * 60

histogram_quantile(
  0.95,
  sum by (le, service, endpoint) (
    rate(
      gurabot_external_request_duration_seconds_bucket{
        service=~"$service"
      }[$__rate_interval]
    )
  )
)

histogram_quantile(
  0.99,
  sum by (le, service, endpoint) (
    rate(
      gurabot_external_request_duration_seconds_bucket{
        service=~"$service"
      }[$__rate_interval]
    )
  )
)

100 *
sum(
  rate(
    gurabot_external_requests_total{
      service=~"$service",
      outcome=~"server_error|timeout|network_error|unknown_error"
    }[$__rate_interval]
  )
)
/
clamp_min(
  sum(
    rate(
      gurabot_external_requests_total{
        service=~"$service"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum by (service, endpoint, outcome) (
  rate(
    gurabot_external_requests_total{
      service=~"$service"
    }[$__rate_interval]
  )
